begin;
select plan(15);
select has_table('public','downtime_id_sequences','downtime IDs have a facility/date sequence');
select has_table('public','downtime_reconciliation_entries','reconciliation metadata is queued in the database');
select has_table('public','downtime_reconciliation_discrepancies','independent discrepancies are tracked');
select has_table('public','downtime_reconciliation_signatures','checker sign-off is recorded');
select has_function('public','next_downtime_id',array['uuid','date'],'downtime identifier allocation RPC is available');
select has_function('public','enter_downtime_reconciliation',array['uuid','text','uuid','text','text','text','text','timestamp with time zone','text','text','text','text'],'paper entry RPC validates downtime ID and metadata');
select has_function('public','check_downtime_reconciliation',array['uuid','boolean','text','text'],'independent checker sign-off RPC is available');
select has_function('public','resolve_downtime_discrepancy',array['uuid','text'],'discrepancy resolution workflow is available');
select has_policy('public','downtime_reconciliation_entries','downtime_entry_read');
select has_policy('public','downtime_reconciliation_discrepancies','downtime_discrepancy_read');
select has_trigger('public','downtime_reconciliation_signatures','downtime_signatures_immutable','checker signatures cannot be changed or deleted');
select ok(not has_table_privilege('authenticated','public.downtime_reconciliation_entries','INSERT'),'entries must use the authorized reconciliation RPC');
select ok(not has_table_privilege('authenticated','public.downtime_reconciliation_entries','UPDATE'),'entry states must use the workflow');
select ok(exists(select 1 from pg_constraint where conrelid='public.downtime_reconciliation_entries'::regclass and contype='u' and pg_get_constraintdef(oid) like '%facility_id, downtime_id%'),'downtime IDs cannot be duplicated within a facility');
select ok(exists(select 1 from pg_constraint where conrelid='public.downtime_reconciliation_signatures'::regclass and contype='c' and pg_get_constraintdef(oid) like '%entered_by%checked_by%'),'independent checker must differ from entering staff');
select * from finish();
rollback;
